export function createFloatLabel(root) {
  if (!root.matches('[data-component="float-label"]') || !root.querySelector('input')) throw new Error('createFloatLabel markup is incomplete.');
  return { destroy() {} };
}
document.querySelectorAll('[data-component="float-label"]').forEach(createFloatLabel);

export function createDatePicker(root) {
  if (!root.matches('[data-component="date-picker"]') || !root.querySelector('input[type="date"]')) throw new Error('createDatePicker markup is incomplete.');
  return { destroy() {} };
}
document.querySelectorAll('[data-component="date-picker"]').forEach(createDatePicker);
